#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<string> grid(N);
    for (auto& row : grid) cin >> row;

    for (int step = 0; step < Q; ++step) {
        vector<string> nextGrid(N, string(N, '0'));

        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                int neighbors = 0;

                for (int di = -1; di <= 1; ++di) {
                    for (int dj = -1; dj <= 1; ++dj) {
                        if (di == 0 && dj == 0) continue;
                        int ni = i + di, nj = j + dj;
                        if (ni >= 0 && ni < N && nj >= 0 && nj < N &&
                            grid[ni][nj] == '1') {
                            ++neighbors;
                        }
                    }
                }

                if (neighbors == 3 ||
                    (grid[i][j] == '1' && neighbors == 2)) {
                    nextGrid[i][j] = '1';
                }
            }
        }

        grid = move(nextGrid);
    }

    for (const auto& row : grid) cout << row << '\n';
    return 0;
}
